utils.update_checkout.update_checkout.co.source_code:
class StatusCommand:
    """
    The status command prints the list of repositories with active changes
    (uncommitted, untracked and/or staged).

    Its goal is to help users determine if it's safe to run the script with
    --reset-to-remote.
    """
    _args: CliArguments
    _pool_args: List[UpdateArguments]

    def __init__(self, args: CliArguments):
        self._args = args
        self._pool_args = []
        for repo_path in args.source_root.iterdir():
            if not is_git_repository(repo_path):
                continue
            repo_name = repo_path.name

            my_args = RunnerArguments(
                repo_name=repo_name,
                output_prefix="Checking the status of",
                source_root=args.source_root,
                verbose=args.verbose,
            )
            self._pool_args.append(my_args)

    def run(self):
        # TODO: If we add more commands, make error handling more generic
        locked_repositories = is_any_repository_locked(self._pool_args)
        if len(locked_repositories) > 0:
            results = [
                Exception(f"'{repo_name}' is locked by git. Cannot update it.")
                for repo_name in locked_repositories
            ]
        else:
            results = ParallelRunner(
                self._get_uncommitted_changes_of_repository,
                self._pool_args,
                self._args.n_processes,
            ).run()

        return self._handle_results(results)

    def _handle_results(self, results) -> int:
        ret = ParallelRunner.check_results(results, "STATUS")
        if ret > 0:
            return ret

        repos_with_active_changes: List[Tuple[str, int]] = []
        for result, pool_arg in zip(results, self._pool_args):
            if result is None or result[0] == "":
                continue
            status_output: str = result[0]
            repos_with_active_changes.append((pool_arg.repo_name, len(status_output.splitlines())))

        if len(repos_with_active_changes) == 0:
            print("No repositories have active changes.")
        else:
            print("The following repositories have active changes:")
            for repo_name, file_count in repos_with_active_changes:
                msg = f"  - [{repo_name}] {file_count} active change"
                if file_count > 1:
                    msg += "s"
                print(msg)

        return 0

    @staticmethod
    def _get_uncommitted_changes_of_repository(pool_args: RunnerArguments):
        repo_path = pool_args.source_root.joinpath(pool_args.repo_name)
        return Git.run(repo_path, ["status", "--short"], fatal=True)

utils.update_checkout.update_checkout.gi.source_code:
class Git:
    @staticmethod
    def run(
        repo_path: Path,
        args: List[str],
        echo: bool = False,
        env: Optional[Dict[str, Any]] = None,
        prefix: str = "",
        allow_non_zero_exit: bool = False,
        fatal: bool = False,
        **kwargs,
    ) -> Tuple[str, int, List[str]]:
        command = Git._build_command(args)
        output = ""
        try:
            result = subprocess.run(
                command,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                universal_newlines=True,
                encoding="utf-8",
                env=env,
                cwd=repo_path,
                **kwargs,
            )
            output = result.stdout
            if echo:
                Git._echo_command(command, output, env, prefix)
            if not allow_non_zero_exit:
                result.check_returncode()
        except subprocess.CalledProcessError as e:
            if fatal:
                sys.exit(
                    f"command `{command}` terminated with a non-zero exit "
                    f"status {str(e.returncode)}, aborting"
                )
            raise GitException(e.returncode, command, repo_path.name, output)
        except OSError as e:
            if fatal:
                sys.exit(
                    f"could not execute '{Git._quote_command(command)}': {e.strerror}"
                )
        return (output.strip(), result.returncode, command)

    @staticmethod
    def _echo_command(
        command: List[str],
        output: Optional[str] = None,
        env: Optional[Dict[str, Any]] = None,
        prefix: str = "",
    ):
        sys.stdout.flush()
        sys.stderr.flush()
        command_str = []
        if env is not None:
            command_str += ["env"] + [
                Git._quote(f"{k}={v}") for (k, v) in sorted(env.items())
            ]
        command_str.append(Git._quote_command(command))
        print(f"{prefix}+ {' '.join(command_str)}", file=sys.stderr)
        if output:
            for line in output.splitlines():
                print(prefix + line)
        sys.stdout.flush()
        sys.stderr.flush()

    @staticmethod
    def _build_command(args: List[str]) -> List[str]:
        return ["git"] + args

    @staticmethod
    def _quote(arg: Any) -> str:
        return shlex.quote(str(arg))

    @staticmethod
    def _quote_command(command: List[Any]) -> str:
        return " ".join(Git._quote(arg) for arg in command)

def is_commit_hash(ref: str):
    """Check if ref looks like a commit hash"""
    return bool(re.match(r'^[0-9a-f]{7,40}$', ref, re.IGNORECASE))

